const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mayfield = ee.Geometry.Point([-88.6364, 36.7417]).buffer(5000); // 5km buffer around Mayfield
  const nov2021 = ['2021-11-01', '2021-11-30'];
  const dec10_12 = ['2021-12-10', '2021-12-12'];

  // 2. Data Acquisition
  function getBrightnessCollection(dateRange) {
    return ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
      .filterDate(dateRange[0], dateRange[1])
      .filterBounds(mayfield)
      .select('avg_rad');
  }

  const novCollection = getBrightnessCollection(nov2021);
  const decCollection = getBrightnessCollection(dec10_12);

  const novSize = novCollection.size().getInfo();
  const decSize = decCollection.size().getInfo();

  console.log(`November 2021 Images: ${novSize}`);
  console.log(`December 10-12 Images: ${decSize}`);

  // Check for empty collections
  if (novSize === 0 || decSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean brightness
  function calculateMeanBrightness(collection) {
    const meanImg = collection.mean();
    const stats = meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: mayfield,
      scale: 1000,
      maxPixels: 1e9
    });
    return stats.get('avg_rad').getInfo();
  }

  const novBrightness = calculateMeanBrightness(novCollection);
  const decBrightness = calculateMeanBrightness(decCollection);

  // 4. Validation & Final Answer
  console.log(`November mean brightness: ${novBrightness}`);
  console.log(`December 10-12 mean brightness: ${decBrightness}`);

  // Check for calculation failures
  if (novBrightness === null || decBrightness === null || 
      isNaN(novBrightness) || isNaN(decBrightness)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare brightness values
  if (novBrightness > decBrightness) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
